        walk(n.id, depth + 1) })
      const roots = pd.nodes.filter(n => !n.parent || !pd.nodes.some(m => m.id === n.parent)); roots.forEach(r => { kids.set('__root', roots) }); walk('__root', 0)
      const cnt = (s: string) => pd.nodes.filter(n => n.status === s).length
