    if (!d) return page()
    // 今天頁 = 流程儀表板(the maintainer 10-14 02:5x 參考圖:上方狀態列、左欄此刻、中間流程框 + 條、下方紀錄、底部一行狀態)
    //   內容照 §22.4:此刻 / 待辦 / 我的包走到哪 / 人格專案應知收一行;雷達與圓餅在「自訂」
    const W = Math.min(120, cols - 4), SW = 30, FW = Math.max(40, W - SW - 2), LBL = labelW(), RL = rowLabelW()
