      out.push([seg('  '), seg(blocks((n / mx) * BW), 'permission'), seg(' '.repeat(BW - Math.round((n / mx) * BW))), seg(num + ' '.repeat(nW - dispW(num)) + '  '), seg(dispW(t) > room ? pad(t, room) : t)])
    }
